window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ad6eeecfc6c64b1"]={"versions": [{"id": "FIG-2ad6eeecfc6c64b1", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der Datentyp-Modellierung innerhalb der AUTOSAR Adaptive Platform (Language Binding for Modeled AP Data Types). Das Diagramm stellt die Vererbungshierarchie und Spezialisierungen von <code>CppImplementationDataType</code> sowie deren Einbettung in das AUTOSAR-Basis-Metamodell dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>AutosarDataType</strong> (<em>ARElement</em>, <em>AtpType</em>): Abstrakte Basisklasse für alle AUTOSAR-Datentypen, fungiert als Ziel der Assoziation <code>+type</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«isOfType»</code>, <code>{redefines atpType}</code>) ausgehend von <code>AutosarDataPrototype</code> (<em>DataPrototype</em>).</li>\n<li><strong>AbstractImplementationDataType</strong> (<em>AtpBlueprint</em>, <em>AtpBlueprintable</em>): Spezialisiert <code>AutosarDataType</code> und bildet die generelle Abstraktion für Implementierungsdatentypen.</li>\n<li><strong>CppImplementationDataType</strong> (<em>CppImplementationDataTypeContextTarget</em>): Spezialisiert <code>AbstractImplementationDataType</code>. Definiert die C++-spezifischen Typattribute:</li>\n<li><code>+ headerFile: String [0..1]</code></li>\n<li><code>+ typeEmitter: NameToken [0..1]</code></li>\n<li><code>+ arraySize: PositiveInteger [0..1]</code> (mit Stereotyp <code>«atpVariation»</code>).</li>\n<li><strong>CustomCppImplementationDataType</strong>: Konkrete Subklasse, spezialisiert <code>CppImplementationDataType</code> zur Modellierung benutzerdefinierter C++-Implementierungsdatentypen.</li>\n<li><strong>StdCppImplementationDataType</strong>: Konkrete Subklasse, spezialisiert <code>CppImplementationDataType</code> zur Modellierung von C++-Standardtypen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert typgebundene Strukturbeziehungen und Spezialisierungen zur Entwurfs- und Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Spezifiziert die zulässigen Metaklassen für modellierte C++-Datentypen im Language Binding.</li>\n<li>Generatoren und Modellierungswerkzeuge müssen zwischen Standardtypen (<code>StdCppImplementationDataType</code>) und anwendungsspezifischen Typen (<code>CustomCppImplementationDataType</code>) unterscheiden.</li>\n<li>Das Attribut <code>arraySize</code> unterliegt der AUTOSAR-Variantenbildung (<code>«atpVariation»</code>) und ist optional (<code>[0..1]</code>).</li>\n<li>Die Header-Inklusion wird über das optionale Attribut <code>headerFile</code> gesteuert, während <code>typeEmitter</code> den zuständigen Codegenerator bzw. Emissionstyp festlegt.</li>\n</ul>"}, {"id": "FIG-834e8d2b8f163964", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der Datentyp-Modellierung innerhalb der AUTOSAR Adaptive Platform (Language Binding for Modeled AP Data Types). Das Diagramm stellt die Vererbungshierarchie und Spezialisierungen von <code>CppImplementationDataType</code> sowie deren Einbettung in das AUTOSAR-Basis-Metamodell dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>AutosarDataType</strong> (<em>ARElement</em>, <em>AtpType</em>): Abstrakte Basisklasse für alle AUTOSAR-Datentypen, fungiert als Ziel der Assoziation <code>+type</code> (Kardinalität <code>0..1</code>, Stereotyp <code>«isOfType»</code>, <code>{redefines atpType}</code>) ausgehend von <code>AutosarDataPrototype</code> (<em>DataPrototype</em>).</li>\n<li><strong>AbstractImplementationDataType</strong> (<em>AtpBlueprint</em>, <em>AtpBlueprintable</em>): Spezialisiert <code>AutosarDataType</code> und bildet die generelle Abstraktion für Implementierungsdatentypen.</li>\n<li><strong>CppImplementationDataType</strong> (<em>CppImplementationDataTypeContextTarget</em>): Spezialisiert <code>AbstractImplementationDataType</code>. Definiert die C++-spezifischen Typattribute:</li>\n<li><code>+ headerFile: String [0..1]</code></li>\n<li><code>+ typeEmitter: NameToken [0..1]</code></li>\n<li><code>+ arraySize: PositiveInteger [0..1]</code> (mit Stereotyp <code>«atpVariation»</code>).</li>\n<li><strong>CustomCppImplementationDataType</strong>: Konkrete Subklasse, spezialisiert <code>CppImplementationDataType</code> zur Modellierung benutzerdefinierter C++-Implementierungsdatentypen.</li>\n<li><strong>StdCppImplementationDataType</strong>: Konkrete Subklasse, spezialisiert <code>CppImplementationDataType</code> zur Modellierung von C++-Standardtypen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Interaktionen oder Laufzeitsequenzen. Es definiert typgebundene Strukturbeziehungen und Spezialisierungen zur Entwurfs- und Generierungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Spezifiziert die zulässigen Metaklassen für modellierte C++-Datentypen im Language Binding.</li>\n<li>Generatoren und Modellierungswerkzeuge müssen zwischen Standardtypen (<code>StdCppImplementationDataType</code>) und anwendungsspezifischen Typen (<code>CustomCppImplementationDataType</code>) unterscheiden.</li>\n<li>Das Attribut <code>arraySize</code> unterliegt der AUTOSAR-Variantenbildung (<code>«atpVariation»</code>) und ist optional (<code>[0..1]</code>).</li>\n<li>Die Header-Inklusion wird über das optionale Attribut <code>headerFile</code> gesteuert, während <code>typeEmitter</code> den zuständigen Codegenerator bzw. Emissionstyp festlegt.</li>\n</ul>"}], "trans": [{"from": "FIG-2ad6eeecfc6c64b1", "to": "FIG-834e8d2b8f163964", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Layout: Die Vererbungshierarchie zwischen <code>AbstractImplementationDataType</code> und <code>AutosarDataType</code> ist von einer vertikalen Anordnung in eine horizontale Anordnung (links nach rechts) umgestellt worden.</li>\n<li>Keine inhaltlichen oder semantischen Änderungen an Klassen, Attributen oder Assoziationen erkennbar.</li>\n</ul>"}]};
